use std::{alloc::{GlobalAlloc,Layout,System},sync::atomic::{AtomicU64,Ordering},path::PathBuf};
struct Count; static CALLS:AtomicU64=AtomicU64::new(0);static BYTES:AtomicU64=AtomicU64::new(0);
unsafe impl GlobalAlloc for Count {unsafe fn alloc(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size()as u64,Ordering::Relaxed);unsafe{System.alloc(l)}} unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size()as u64,Ordering::Relaxed);unsafe{System.alloc_zeroed(l)}} unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n as u64,Ordering::Relaxed);unsafe{System.realloc(p,l,n)}} unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}}
#[global_allocator]static ALLOC:Count=Count;
